import { createMemo, For, Show, splitProps, type Component, type JSX } from "solid-js";

import {
	getModifierTextByContext,
	parseConstructibleAdjacencyNameOnly,
} from "#core/ui/utilities/utilities-core-textprovider.js";
import { Icon } from "#core/ui-next/components/icon.jsx";
import { L10n } from "#core/ui-next/components/l10n.jsx";

import { ConstructibleHasTagType, getConstructibleTagsFromType } from "#base/ui/utilities/utilities-tags.js";
import { PillText } from "#base/ui-next/components/pills.jsx";

type MaybeString = string | null | undefined;
type DividerStyle = "normal" | "text-divider";
type SelectedCity = ReturnType<typeof Cities.get> | null;

interface YieldChangeInfo {
	yieldType: string;
	amount: number;
}

interface MaintenanceEntry {
	yieldType: string;
	value: number;
}

interface AdjacencyGroup {
	id: string;
	textKey: string;
	args: LocalizedTextArgument[];
	listMarkup?: string;
}

const bulletChar = String.fromCodePoint(0x2022);

// Legacy tooltips rely on manual spacing, so mirror the original bullet adjustments.
const formatStylizedSpacing = (element: HTMLDivElement | undefined) => {
	if (!element) {
		return;
	}
	let firstChild = true;
	let prevChildIsList = false;
	for (const node of Array.from(element.children)) {
		const isList = node.innerHTML.includes(bulletChar);
		if (isList) {
			node.classList.add("ml-4");
		}
		if (!firstChild && (!prevChildIsList || !isList)) {
			node.classList.add("mt-2");
		}
		firstChild = false;
		prevChildIsList = isList;
	}
};

const collectYieldChanges = (constructibleType?: MaybeString): YieldChangeInfo[] => {
	if (!constructibleType) {
		return [];
	}
	const results: YieldChangeInfo[] = [];
	for (const entry of GameInfo.Constructible_YieldChanges) {
		if (entry.ConstructibleType === constructibleType) {
			results.push({ amount: entry.YieldChange, yieldType: entry.YieldType });
		}
	}
	return results;
};

const collectModifierTexts = (constructibleType?: MaybeString): string[] => {
	if (!constructibleType) {
		return [];
	}
	const modifiers: string[] = [];
	for (const modifier of GameInfo.ConstructibleModifiers) {
		if (modifier.ConstructibleType === constructibleType) {
			const text = getModifierTextByContext(modifier.ModifierId, "Description");
			if (text) {
				modifiers.push(text);
			}
		}
	}
	return modifiers;
};

const collectUnlockedGreatPeople = (constructibleType: MaybeString, selectedCity: SelectedCity): string[] => {
	const unlocksGreatPeople: string[] = [];
	if (!constructibleType || !selectedCity) return unlocksGreatPeople;

	const playerID = selectedCity.owner;
	const playerUnits = Players.Units.get(playerID);
	if (!playerUnits) return unlocksGreatPeople;

	GameInfo.GreatPersonClasses.forEach((greatPersonClass) => {
		if (!greatPersonClass.ConstructibleType && !greatPersonClass.ConstructibleTag) return;
		if (greatPersonClass.ConstructibleType) {
			if (greatPersonClass.ConstructibleType !== constructibleType) return;
		}
		if (greatPersonClass.ConstructibleTag) {
			if (!ConstructibleHasTagType(constructibleType, greatPersonClass.ConstructibleTag)) return;
		}

		const greatPersonUnitDef = GameInfo.Units.lookup(greatPersonClass.UnitType);

		if (greatPersonUnitDef && playerUnits.canEverTrain(greatPersonClass.UnitType)) {
			const unitName = greatPersonUnitDef.Description
				? `[TIP:${greatPersonUnitDef.Description}]{${greatPersonUnitDef.Name}}[/TIP]`
				: greatPersonUnitDef.Name;

			unlocksGreatPeople.push(
				Locale.compose("LOC_UI_PRODUCTION_ALLOWS_TRAINING", greatPersonUnitDef.UnitType, unitName),
			);
		}
	});

	return unlocksGreatPeople;
};

const collectMaintenanceEntries = (constructibleType: MaybeString, selectedCity: SelectedCity): MaintenanceEntry[] => {
	if (!constructibleType || !selectedCity) {
		return [];
	}
	const values = selectedCity.Constructibles?.getMaintenance(constructibleType);
	if (!values || values.length === 0) {
		return [];
	}
	const entries: MaintenanceEntry[] = [];
	for (let index = 0; index < values.length; index += 1) {
		const amount = values[index];
		if (amount > 0) {
			const yieldDefinition = GameInfo.Yields[index];
			if (yieldDefinition) {
				entries.push({ yieldType: yieldDefinition.YieldType, value: amount });
			}
		}
	}
	return entries;
};

const buildAdjacencyListMarkup = (entries: Adjacency_YieldChangeDefinition[]): string => {
	const items = entries.map((definition) => `[LI] ${parseConstructibleAdjacencyNameOnly(definition)}`).join("");
	return `[BLIST]${items}[/BLIST]`;
};

// Group adjacency data by yield type and change value to match the legacy layout.
const collectAdjacencyGroups = (constructibleType: MaybeString, selectedCity: SelectedCity): AdjacencyGroup[] => {
	if (!constructibleType) {
		return [];
	}
	const adjacencyDefinitions: Adjacency_YieldChangeDefinition[] = [];
	for (const definition of GameInfo.Constructible_Adjacencies) {
		if (definition.ConstructibleType !== constructibleType) {
			continue;
		}
		const yieldChangeDef = GameInfo.Adjacency_YieldChanges.find((entry) => entry.ID === definition.YieldChangeId);
		if (!yieldChangeDef) {
			continue;
		}
		if (definition.RequiresActivation && selectedCity?.Constructibles) {
			if (!selectedCity.Constructibles.isAdjacencyUnlocked(yieldChangeDef.ID)) {
				continue;
			}
		}
		adjacencyDefinitions.push(yieldChangeDef);
	}
	if (adjacencyDefinitions.length === 0) {
		return [];
	}
	const groups: AdjacencyGroup[] = [];
	let counter = 0;
	for (const yieldDefinition of GameInfo.Yields) {
		const perChangeMap = new Map<number, Adjacency_YieldChangeDefinition[]>();
		for (const changeDefinition of adjacencyDefinitions) {
			if (changeDefinition.YieldType !== yieldDefinition.YieldType) {
				continue;
			}
			const list = perChangeMap.get(changeDefinition.YieldChange);
			if (list) {
				list.push(changeDefinition);
			} else {
				perChangeMap.set(changeDefinition.YieldChange, [changeDefinition]);
			}
		}
		perChangeMap.forEach((definitions, value) => {
			const id = `${yieldDefinition.YieldType}-${value}-${counter}`;
			counter += 1;
			if (definitions.length <= 1) {
				groups.push({
					id,
					textKey: "LOC_UI_ADJACENCY_INFO_OBJECT",
					args: [
						value,
						`[icon:${yieldDefinition.YieldType}]`,
						parseConstructibleAdjacencyNameOnly(definitions[0]),
					],
				});
				return;
			}
			groups.push({
				id,
				textKey: "LOC_UI_ADJACENCY_INFO_GENERIC",
				args: [value, yieldDefinition.YieldType],
				listMarkup: buildAdjacencyListMarkup(definitions),
			});
		});
	}
	return groups;
};

const shouldShowBonus = (value?: MaybeString): boolean => value !== undefined && value !== null && value !== "";

export interface ConstructibleDetailsProps extends JSX.HTMLAttributes<HTMLDivElement> {
	definition: ConstructibleDefinition;
	isPurchase?: boolean;
	dividerStyle?: DividerStyle;
	warehouseBonus?: MaybeString;
	adjacencyBonus?: MaybeString;
	cost?: number;
}

export const ConstructibleDetails: Component<ConstructibleDetailsProps> = (props) => {
	const [local, other] = splitProps(props, [
		"definition",
		"isPurchase",
		"dividerStyle",
		"warehouseBonus",
		"adjacencyBonus",
		"cost",
		"class",
	]);

	const selectedCity = createMemo<SelectedCity>(() => {
		const cityID = UI.Player.getHeadSelectedCity();
		return cityID ? Cities.get(cityID) : null;
	});
	const dividerStyle = createMemo<DividerStyle>(() => local.dividerStyle ?? "normal");
	const tags = createMemo(() => {
		const type = props.definition.ConstructibleType;
		return type ? getConstructibleTagsFromType(type) : [];
	});
	const baseYields = createMemo(() => collectYieldChanges(props.definition.ConstructibleType));
	const modifierTexts = createMemo(() => collectModifierTexts(props.definition.ConstructibleType));
	const tooltipText = createMemo(() => props.definition.Tooltip ?? "");
	const greatPeopleTexts = createMemo(() =>
		collectUnlockedGreatPeople(props.definition.ConstructibleType, selectedCity()),
	);
	const showTooltip = createMemo(() => !!tooltipText());

	const costIcon = createMemo(() => (local.isPurchase ? "YIELD_GOLD" : "YIELD_PRODUCTION"));
	const maintenanceEntries = createMemo(() =>
		collectMaintenanceEntries(props.definition.ConstructibleType, selectedCity()),
	);
	const adjacencyGroups = createMemo(() =>
		collectAdjacencyGroups(props.definition.ConstructibleType, selectedCity()),
	);

	const showWarehouseBonus = createMemo(() => shouldShowBonus(local.warehouseBonus));
	const showAdjacencyBonus = createMemo(() => shouldShowBonus(local.adjacencyBonus));

	const showMidSection = createMemo(() => {
		return (
			baseYields().length > 0 ||
			adjacencyGroups().length > 0 ||
			modifierTexts().length > 0 ||
			greatPeopleTexts().length > 0 ||
			showTooltip()
		);
	});

	const showBottomSection = createMemo(() => {
		return local.cost != 0 || maintenanceEntries().length > 0 || showWarehouseBonus() || showAdjacencyBonus();
	});

	return (
		<div
			class={`mt-10 img-base-ticket-bg-container ${local.class ?? ""}`}
			{...other}
		>
			<Icon
				class="size-20 self-center -mt-16 mb-2\.5"
				name={props.definition.ConstructibleType ?? undefined}
			/>
			<div class="w-full flex flex-wrap self-center justify-center">
				<For each={tags()}>
					{(tag) => (
						<PillText
							class="mx-1 mb-2 text-sm"
							text={tag}
						/>
					)}
				</For>
			</div>
			<Show when={showMidSection()}>
				<Show
					when={dividerStyle() === "text-divider"}
					fallback={<div class="img-shell-line-divider h-1 w-1/2 self-center mb-2" />}
				>
					<div class="flex items-center w-full">
						<div class="constructible-details__divider-line-left" />
						<p class="mx-2 font-title text-secondary text-sm uppercase">
							<L10n.Compose text="LOC_UI_CONTENT_MGR_DETAILS" />
						</p>
						<div class="constructible-details__divider-line-right" />
					</div>
				</Show>
				<Show when={baseYields().length > 0}>
					<div class="mb-2 flex flex-wrap">
						<For each={baseYields()}>
							{(yieldValue) => (
								<L10n.Stylize
									class="mr-2"
									text="LOC_UI_POS_YIELD_ICON_ONLY"
									args={[yieldValue.amount, yieldValue.yieldType]}
								/>
							)}
						</For>
					</div>
				</Show>
				<Show when={adjacencyGroups().length > 0}>
					<div class="mb-2">
						<For each={adjacencyGroups()}>
							{(group, index) => (
								<div>
									<L10n.Stylize
										class={`block ${index() > 0 ? "mt-2" : ""} ${group.listMarkup ? "mb-2" : ""}`.trim()}
										text={group.textKey}
										args={group.args}
									/>
									<Show when={group.listMarkup}>
										{(listText) => (
											<L10n.Stylize
												class="ml-4"
												text={listText() ?? ""}
											/>
										)}
									</Show>
								</div>
							)}
						</For>
					</div>
				</Show>
				<Show when={modifierTexts().length > 0}>
					<div class="mb-2">
						<For each={modifierTexts()}>
							{(text, index) => (
								<L10n.Stylize
									class={`block ${index() > 0 ? "mt-1" : ""}`.trim()}
									text={text}
								/>
							)}
						</For>
					</div>
				</Show>
				<Show when={showTooltip()}>
					<L10n.Stylize
						class="mb-2"
						text={tooltipText()}
						ref={formatStylizedSpacing}
					/>
				</Show>
				<Show when={greatPeopleTexts().length > 0}>
					<div class="mb-2">
						<For each={greatPeopleTexts()}>
							{(text, index) => (
								<L10n.Stylize
									class={`block ${index() > 0 ? "mt-1" : ""}`.trim()}
									text={text}
								/>
							)}
						</For>
					</div>
				</Show>
			</Show>
			<Show when={showBottomSection()}>
				<div class="img-shell-line-divider h-1 w-1/2 self-center mb-2" />
				<Show when={local.cost}>
					{(cost) => (
						<L10n.Stylize
							text="LOC_UI_PRODUCTION_CONSTRUCTIBLE_COST"
							args={[cost(), costIcon()]}
						/>
					)}
				</Show>
				<Show when={maintenanceEntries().length > 0}>
					<div class="flex items-center">
						<div class="mr-2">
							<L10n.Compose text="LOC_UI_PRODUCTION_MAINTENANCE" />
						</div>
						<For each={maintenanceEntries()}>
							{(entry) => (
								<L10n.Stylize
									class="mr-2"
									text="LOC_UI_PRODUCTION_MAINTENANCE_NEGATIVE_VALUE"
									args={[entry.value, entry.yieldType]}
								/>
							)}
						</For>
					</div>
				</Show>
				<Show when={showWarehouseBonus()}>
					<div class="flex mb-2 items-center">
						<div class="mr-2">
							<L10n.Compose text="LOC_BUILDING_PLACEMENT_WAREHOUSE_IMPROVEMENTS" />
						</div>
						<L10n.Stylize
							class="mr-2"
							text="{1_amount} [icon:{2_icon}]"
							args={[local.warehouseBonus!, "YIELD_WAREHOUSE"]}
						/>
					</div>
				</Show>
				<Show when={showAdjacencyBonus()}>
					<div class="flex mb-2 items-center">
						<div class="mr-2">
							<L10n.Compose text="LOC_BUILDING_PLACEMENT_HIGHEST_ADJACENCIES" />
						</div>
						<L10n.Stylize
							class="mr-2"
							text="{1_amount} [icon:{2_icon}]"
							args={[local.adjacencyBonus!, "YIELD_ADJACENCY"]}
						/>
					</div>
				</Show>
			</Show>
		</div>
	);
};
